 static RebirthPoiPartialObservation Partial(Guid generation,long revision,IEnumerable<RebirthPoiActorObservation> actors,long epoch=0)=>new RebirthPoiPartialObservation(generation,epoch,revision,new[]{new RebirthPoiVolumeObservation(7,new string('a',64),actors)});
