 {
  object scope=new object();Guid world=Guid.NewGuid(),generation=Guid.NewGuid(),token=Guid.NewGuid(),death=Guid.NewGuid();var poi=new RebirthPoiIdentity("house",1,2,3,0,10,10,10,"forest");var ledger=new RebirthPoiClearanceLedger(world,scope);ledger.TryDiscover(scope,world,0,poi,out ledger);
  var actor=new RebirthPoiActorObservation(token,1,"zombieArlene",0);var original=Partial(generation,1,new[]{actor});Check(ledger.TryObservePartial(scope,world,ledger.Revision,poi,0,original,out ledger),"actual domain accepts first original observation generation");string xml=RebirthPoiClearanceCodec.Write(ledger);Check(RebirthPoiClearanceCodec.TryRead(xml,world,scope,out var restored)&&restored.Records[poi.Key].Observations.Canonical==original.Canonical,"cold codec retains exact native actor generation and manifest");Check(!RebirthPoiClearanceCodec.TryRead(xml,Guid.NewGuid(),scope,out _),"partial journal original world enforced");Check(!ledger.TryObservePartial(new object(),world,ledger.Revision,poi,0,original,out _),"partial original scope enforced");Check(ledger.TryObservePartial(scope,world,0,poi,0,original,out var same)&&ReferenceEquals(same,ledger),"original observation duplicate retains global revision");
  var died=new RebirthPoiActorObservation(token,1,"zombieArlene",0,death,42);var terminal=Partial(generation,2,new[]{died});Check(ledger.TryObservePartial(scope,world,ledger.Revision,poi,0,terminal,out ledger),"original death receipt is durable monotonic successor");Check(!ledger.TryObservePartial(scope,world,ledger.Revision,poi,0,Partial(generation,3,new[]{actor}),out _),"dead actor cannot revive in same generation");Check(!ledger.TryObservePartial(scope,world,ledger.Revision,poi,0,Partial(generation,3,new RebirthPoiActorObservation[0]),out _),"old enrolled actor cannot disappear");Check(!ledger.TryObservePartial(scope,world,ledger.Revision,poi,0,Partial(Guid.NewGuid(),3,new[]{died}),out _),"replacement generation cannot reuse same epoch");Check(!ledger.TryObservePartial(scope,world,ledger.Revision-1,poi,0,Partial(generation,3,new[]{died}),out _),"stale global predecessor refused");
  Guid reset=Guid.NewGuid();ledger.TryBeginReset(scope,world,ledger.Revision,poi,0,reset,out ledger);Check(!ledger.TryObservePartial(scope,world,ledger.Revision,poi,0,terminal,out _),"pending reset blocks observations");ledger.TryFinishReset(scope,world,ledger.Revision,poi,0,reset,RebirthPoiResetDisposition.NoMutation,out ledger);Check(ledger.Records[poi.Key].Observations.Canonical==terminal.Canonical,"proven no mutation restores original partial causality");reset=Guid.NewGuid();ledger.TryBeginReset(scope,world,ledger.Revision,poi,0,reset,out ledger);ledger.TryFinishReset(scope,world,ledger.Revision,poi,0,reset,RebirthPoiResetDisposition.Completed,out ledger);Check(ledger.Records[poi.Key].Epoch==1&&ledger.Records[poi.Key].Observations==null,"proven completed reset advances epoch and forgets old generation");
  Check(!RebirthPoiClearanceCodec.TryRead(xml.Replace("<observations ","<observations unknown=\"1\" "),world,scope,out _),"unknown observation attribute refused");Check(!RebirthPoiClearanceCodec.TryRead(xml+"<!--extra-->",world,scope,out _),"whole envelope remains strict with observation payload");
  string dir=Path.Combine(Path.GetTempPath(),"rebirth-purge-observation-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var binding=new RebirthPoiWorldBinding(scope,world.ToString("N").ToUpperInvariant(),dir,()=>true);bool armed=false;string faultStage="afterShardWrite";int written=0;Check(RebirthPoiWorldStore.TryOpen(binding,out var store,stage=>{if(armed&&stage==faultStage&&++written==1)throw new IOException("first repack file lost response");})==RebirthPoiStoreResult.Published,"production store opens real observation save");
  for(int i=0;i<110;i++){var p=new RebirthPoiIdentity("house"+i,i,2,3,0,10,10,10,"forest");if(store.TryDiscover(store.Published,p)!=RebirthPoiStoreResult.Published)throw new Exception("setup discover "+i);}
  Check(store.Published.Count==110,"prepare110 real saved POIs");
  var target=new RebirthPoiIdentity("house0",0,2,3,0,10,10,10,"forest");var actors=Enumerable.Range(0,2070).Select(i=>new RebirthPoiActorObservation(Guid.NewGuid(),10000+i,new string('z',256),i%255)).ToArray();var large=Partial(Guid.NewGuid(),1,actors);int oldShards=store.Published.Shards.Count;armed=true;var predecessor=store.Published;Check(store.TryObservePartial(predecessor,target,0,large)==RebirthPoiStoreResult.Uncertain&&store.HasPending&&store.Published.Revision==predecessor.Revision,"repack first file interruption preserves original visible global revision");var originalFiles=Directory.GetFiles(binding.Directory,"shard-*.xml");armed=false;Check(store.TryRetryPending()==RebirthPoiStoreResult.Published,"original multi-shard candidate retry publishes");Check(store.Published.Shards.Count==oldShards+1&&store.Published.Count==110,"payload budget repacks one POI with exact map cardinality");Check(originalFiles.All(File.Exists),"uncertain repack immutable files preserved");Check(store.Published.TryGet(target,out var saved)&&saved.Observations.Canonical==large.Canonical,"actual final witness contains original partial payload");Check(RebirthPoiWorldStore.TryOpen(binding,out var cold)==RebirthPoiStoreResult.Published&&cold.Published.Count==110&&cold.Published.TryGet(target,out saved)&&saved.Observations.Volumes[7].Actors.Count==2070,"cold actual file reload verifies both repacked shards and all actors");Check(cold.TryObservePartial(cold.Published,target,0,large)==RebirthPoiStoreResult.Duplicate,"cold original partial retry idempotent");Check(cold.TryObservePartial(predecessor,target,0,large)==RebirthPoiStoreResult.Conflict,"pre-repack scope snapshot cannot publish late operation");
  var nextTarget=new RebirthPoiIdentity("house1",1,2,3,0,10,10,10,"forest");var nextLarge=Partial(Guid.NewGuid(),1,actors.Select(a=>new RebirthPoiActorObservation(Guid.NewGuid(),a.EntityId,a.ClassName,a.SpawnPoint)));armed=true;written=0;faultStage="afterManifestCandidateWritten";var before=store.Published;Check(store.TryObservePartial(before,nextTarget,0,nextLarge)==RebirthPoiStoreResult.Uncertain,"two-shard final candidate interruption remains uncertain");string retained=File.ReadAllText(Path.Combine(binding.Directory,"world.xml.candidate"));Check(RebirthPoiWorldStore.TryOpen(binding,out var restarted)==RebirthPoiStoreResult.Uncertain&&restarted.Published.Revision==before.Revision,"restart preserves original predecessor for retained two-shard candidate");Check(restarted.TryRetryPending()==RebirthPoiStoreResult.Published&&restarted.Published.Manifest==retained&&restarted.Published.Count==110,"restart exact two-shard candidate publishes unchanged envelope");Check(restarted.Published.TryGet(nextTarget,out saved)&&saved.Observations.Canonical==nextLarge.Canonical,"restart original partial causality survives full publication interruption");
  var malformed=System.Xml.Linq.XDocument.Parse(xml);var observations=malformed.Root.Element("poi").Element("observations");var firstVolume=observations.Element("volume");firstVolume.Add(new System.Xml.Linq.XElement(firstVolume.Element("actor")));Check(!RebirthPoiClearanceCodec.TryRead(malformed.ToString(),world,scope,out _),"duplicate persisted native actor token refused");bool invalid=false;try{new RebirthPoiActorObservation(Guid.NewGuid(),5,"bad"+'\ud800',0);}catch(System.Xml.XmlException){invalid=true;}Check(invalid,"invalidUTF16 actor identity refused");
