  var rooms=new RebirthPoiPartialObservation(generation,0,1,new[]{roomA,roomB});var resetPlan=new RebirthPoiResetPlan(Guid.NewGuid(),RebirthPoiResetCaller.NaturalRespawn,new string('c',64),new long[0],new[]{7},new int[0]);var rolled=rooms.RollOverVerifiedReset(resetPlan);
  Check(rolled.Epoch==1&&rolled.Revision==2&&rolled.Volumes[7].Actors.Count==0&&rolled.EffectiveGeneration(rolled.Volumes[7])==resetPlan.Transaction,"exact selective reset stamps affected volume original transaction");
  Check(rolled.Volumes[8].Actors.Values.Single().DeathReceipt==roomB.Actors.Values.Single().DeathReceipt&&rolled.EffectiveGeneration(rolled.Volumes[8])==generation,"positively untouched room retains original generation and death receipt");
  Check(rolled.Canonical==rooms.RollOverVerifiedReset(resetPlan).Canonical,"selective successor is deterministic under original retry");
  Check(rooms.RollOverVerifiedReset(new RebirthPoiResetPlan(Guid.NewGuid(),RebirthPoiResetCaller.NaturalRespawn,new string('c',64),new long[0],new[]{9},new int[0]))==null,"unknown reset volume cannot preserve partial evidence");
  var v2=RebirthPoiPartialObservation.Write(rolled);Check(RebirthPoiPartialObservation.Read(v2).Canonical==rolled.Canonical,"version3 explicit per-volume generations round trip");
  var v1=RebirthPoiPartialObservation.Write(rooms);v1.SetAttributeValue("version",1);foreach(var v in v1.Elements("volume"))v.Attribute("generation").Remove();var legacy=RebirthPoiPartialObservation.Read(v1);
  Check(legacy.Volumes.Values.All(v=>legacy.EffectiveGeneration(v)==generation),"backward version1 volumes resolve original journal generation");
  var replacedGeneration=new RebirthPoiPartialObservation(generation,0,2,new[]{new RebirthPoiVolumeObservation(7,new string('a',64),new[]{died},Guid.NewGuid()),roomB});Check(!replacedGeneration.IsSuccessorOf(rooms),"normal observation cannot replace volume generation without reset");
  Guid restoreReceipt=Guid.NewGuid();var replacement=actor.RestoreVerifiedNativeParticipant(11,restoreReceipt);var restoreJournal=Partial(generation,2,new[]{replacement});Check(restoreJournal.IsSuccessorOf(original),"explicit native restoration preserves logical participant with new entity ID");
  Check(replacement.Token==actor.Token&&replacement.Restorations.Single().FromEntityId==1&&replacement.Restorations.Single().ToEntityId==11,"lineage retains exact original participant and predecessor");
  Check(RebirthPoiPartialObservation.Read(RebirthPoiPartialObservation.Write(restoreJournal)).Canonical==restoreJournal.Canonical,"strict persisted restoration chain cold round trip");
  Check(!Partial(generation,2,new[]{new RebirthPoiActorObservation(token,11,"zombieArlene",0)}).IsSuccessorOf(original),"new ID without positive restoration receipt refused");
  Check(!Partial(generation,3,new[]{new RebirthPoiActorObservation(token,11,"zombieArlene",0)}).IsSuccessorOf(restoreJournal),"original restoration receipt cannot be forgotten");
  var replacementDead=new RebirthPoiActorObservation(token,11,"zombieArlene",0,Guid.NewGuid(),45,replacement.Restorations);Check(Partial(generation,3,new[]{replacementDead}).IsSuccessorOf(restoreJournal),"restored participant original lineage retained through actual death");
  bool deadRestore=false;try{replacementDead.RestoreVerifiedNativeParticipant(12,Guid.NewGuid());}catch(InvalidOperationException){deadRestore=true;}Check(deadRestore,"witnessed dead logical participant cannot be restored");
  bool cyclic=false;try{replacement.RestoreVerifiedNativeParticipant(1,Guid.NewGuid());}catch(ArgumentException){cyclic=true;}Check(cyclic,"restoration native ID cycles refused");
  bool duplicateReceipt=false;try{replacement.RestoreVerifiedNativeParticipant(12,restoreReceipt);}catch(ArgumentException){duplicateReceipt=true;}Check(duplicateReceipt,"original restoration receipt cannot alias a second native replacement");
  var repeated=actor;for(int i=0;i<32;i++)repeated=repeated.RestoreVerifiedNativeParticipant(20+i,Guid.NewGuid());var compacted=repeated.RestoreVerifiedNativeParticipant(99,Guid.NewGuid());Check(compacted.Checkpoint.Count==32&&compacted.Restorations.Count==1&&compacted.IsCausalSuccessorOf(repeated),"exact deterministic checkpoint supports restoration beyond32 without unbounded history");
  var many=compacted;for(int i=0;i<200;i++)many=many.RestoreVerifiedNativeParticipant(100+i,Guid.NewGuid());Check(many.Checkpoint.Count+many.Restorations.Count==233&&many.Restorations.Count<=32,"233restorations retain bounded current lineage and cumulative count");
  Check(RebirthPoiPartialObservation.Read(RebirthPoiPartialObservation.Write(Partial(generation,3,new[]{many}))).Canonical==Partial(generation,3,new[]{many}).Canonical,"compacted native lineage strict cold round trip");
